class TopicMirror:
    """A hub topic mirrored on the client: it subscribes, asks the hub for a snapshot, then
    applies what arrives after the snapshot's ``seq``. It asks again when the publishing
    instance's ``epoch`` changes, when a collection topic skips a ``seq``, and after the
    connection reconnects. Subclasses say what a snapshot and a delta mean."""

    #: Whether a skipped ``seq`` loses state (a delta topic) or not (snapshot topics).
    gaps_lose_state = False

    def __init__(self, runtime: KitRuntime, node_type: str, key: str, topic: str) -> None:
        self.runtime = runtime
        self.node_type = node_type
        self.key = key
        self.topic = topic
        self._state: Any = None
        self._epoch = -1
        self._seq = 0
        self._buffer: list[tuple[KitHeader, dict[str, Any]]] | None = None
        self._lock = threading.Lock()
        self._sync: SingleFlight[Any] = SingleFlight()
        self._stop: Callable[[], Awaitable[None]] | None = None
        self._off_reconnect: Callable[[], None] | None = None
        self._started = False
        self._changes = _Listeners()
        self._events = _Listeners()
        self._changed = _Listeners()

    def _from_snapshot(self, body: dict[str, Any]) -> Any:
        return body

    def _apply_delta(self, state: Any, delta: dict[str, Any]) -> Any:
        """The state after one delta, or ``None`` when a delta is not this topic's (resync)."""
        return None

    def start(self) -> Any:
        """Subscribes and takes the first snapshot; returns the state. Idempotent."""
        if self._started:
            return self._state
        self._off_reconnect = self.runtime.on_reconnect(lambda _host: run_in_thread(self.resync))
        try:
            self._stop = self.runtime.subscribe(
                self.node_type, self.key, self.topic, self._on_push
            )
            state = self.resync()
        except BaseException:
            self.stop()
            raise
        self._started = True
        return state

    def stop(self) -> None:
        """Stops the subscription; the last state stays readable."""
        if self._off_reconnect is not None:
            self._off_reconnect()
            self._off_reconnect = None
        stop, self._stop = self._stop, None
        self._started = False
        if stop is not None:
            stop()

    def resync(self) -> Any:
        """Takes a fresh snapshot (shared by concurrent callers)."""
        return self._sync.run(self._snapshot)

    def _snapshot(self) -> Any:
        with self._lock:
            self._buffer = []
        try:
            reply = self.runtime.call(
                self.node_type, self.key, KIT_SNAPSHOT_METHOD, {"topic": self.topic}
            )
        except BaseException:
            with self._lock:
                self._buffer = None
            raise
        msg = split_kit_message(reply)
        if msg is None:
            with self._lock:
                self._buffer = None
            raise KitError(
                "bad_request",
                f"{self.node_type} answered snapshot with something other than a kit message",
            )
        header, body = msg
        resync = False
        with self._lock:
            self._epoch, self._seq = header.epoch, header.seq
            self._state = self._from_snapshot(body)
            pending = sorted(self._buffer or [], key=lambda m: m[0].seq)
            self._buffer = None
            fired: list[tuple[str, Any, KitHeader]] = []
            for m in pending:
                resync = self._apply(m, fired) or resync
            state = self._state
        self._changes.fire(state)
        self._fire(fired)
        if resync:
            run_in_thread(self.resync)
        return state

    def get(self) -> Any:
        return self._state

    def subscribe(self, listener: Callable[[Any], Any]) -> Callable[[], None]:
        """Calls ``listener`` with the state after every change; returns the function that
        stops it."""
        return self._changes.add(listener)

    def on_event(self, listener: Callable[[dict[str, Any], KitHeader], Any]) -> Callable[[], None]:
        """``event`` messages on the topic."""
        return self._events.add(listener)

    def on_changed(
        self, listener: Callable[[dict[str, Any], KitHeader], Any]
    ) -> Callable[[], None]:
        """``changed`` messages on the topic: someone's private state to read again."""
        return self._changed.add(listener)

    @property
    def position(self) -> tuple[int, int]:
        """The epoch and seq the mirror is at; ``-1`` before its first snapshot."""
        return self._epoch, self._seq

    def _on_push(self, push: ExecPush) -> None:
        msg = split_kit_message(push.value)
        if msg is None:
            return
        fired: list[tuple[str, Any, KitHeader]] = []
        with self._lock:
            if self._buffer is not None:
                self._buffer.append(msg)
                return
            resync = self._apply(msg, fired)
            state = self._state
        if any(kind == "state" for kind, _, _ in fired):
            self._changes.fire(state)
        self._fire(fired)
        if resync:
            run_in_thread(self.resync)

    def _fire(self, fired: list[tuple[str, Any, KitHeader]]) -> None:
        for kind, body, header in fired:
            if kind == "event":
                self._events.fire(body, header)
            elif kind == "changed":
                self._changed.fire(body, header)

    def _apply(
        self, msg: tuple[KitHeader, dict[str, Any]], fired: list[tuple[str, Any, KitHeader]]
    ) -> bool:
        """Applies one message (under the lock); returns whether a resync is needed."""
        header, body = msg
        if header.epoch != self._epoch:
            if header.kind != "snapshot":
                return True
            self._epoch, self._seq = header.epoch, header.seq
            self._state = self._from_snapshot(body)
            fired.append(("state", None, header))
            return False
        if header.seq <= self._seq:
            return False
        gap = header.seq != self._seq + 1
        self._seq = header.seq
        if header.kind == "snapshot":
            self._state = self._from_snapshot(body)
            fired.append(("state", None, header))
            return False
        if header.kind == "delta":
            nxt = None if gap or self._state is None else self._apply_delta(self._state, body)
            if nxt is None:
                return True
            self._state = nxt
            fired.append(("state", None, header))
            return False
        fired.append(("changed" if header.kind == "changed" else "event", body, header))
        return gap and self.gaps_lose_state


class HubState(TopicMirror):
    """A topic whose messages are its hub's whole public state (``snapshot`` messages)."""


class CollectionMirror(TopicMirror):
    """A topic carrying a collection (``delta`` per member; the snapshot's ``containers``): the
    starters' model topics, such as an area's mobs, NPCs and pets. Its state is a dict of
    :class:`KitContainer` by id."""

    gaps_lose_state = True

    def _from_snapshot(self, body: dict[str, Any]) -> dict[int, KitContainer]:
        out: dict[int, KitContainer] = {}
        for c in body.get("containers") or []:
            if not c.get("removed") and isinstance(c.get("id"), int):
                out[c["id"]] = KitContainer(c["id"], c.get("type_name") or "", c.get("props") or {})
        return out

    def _apply_delta(
        self, state: dict[int, KitContainer], delta: dict[str, Any]
    ) -> dict[int, KitContainer] | None:
        mid = delta.get("id")
        if not isinstance(mid, int) or isinstance(mid, bool):
            return None
        nxt = dict(state)
        if delta.get("removed"):
            nxt.pop(mid, None)
        else:
            held = state.get(mid)
            type_name = delta.get("type_name") or (held.type_name if held else "")
            nxt[mid] = KitContainer(mid, type_name, delta.get("props") or {})
        return nxt

    def list(self, type_name: str | None = None) -> builtins.list[KitContainer]:
        """The members, oldest first, of one type or all."""
        members = sorted((self._state or {}).values(), key=lambda c: c.id)
        return [c for c in members if c.type_name == type_name] if type_name else members

    def member(self, id: int) -> KitContainer | None:
        """One member by id."""
        return (self._state or {}).get(id)


class PrivateState:
    """State only its player may read (a hand of cards, an inventory, a pet's bond): read with
    a caller-scoped call, read again when the hub's ``changed`` message names this player, and
    after a reconnect. Nothing private is ever on a topic.

    ``read`` reads the value with a call the hub answers for its caller alone; ``what`` names
    the ``changed`` messages that concern it.
    """

    def __init__(
        self,
        runtime: KitRuntime,
        *,
        node_type: str,
        key: str,
        topic: str,
        what: str | tuple[str, ...] | list[str],
        read: Callable[[], Awaitable[Any]],
    ) -> None:
        self.runtime = runtime
        self.node_type = node_type
        self.key = key
        self.topic = topic
        self._whats = frozenset([what] if isinstance(what, str) else what)
        self._read = read
        self._value: Any = None
        self._reading: SingleFlight[Any] = SingleFlight()
        self._again = False
        self._stop: Callable[[], Awaitable[None]] | None = None
        self._off_reconnect: Callable[[], None] | None = None
        self._started = False
        self._listeners = _Listeners()

    def start(self) -> Any:
        """Subscribes and reads the first value. Idempotent."""
        if self._started:
            return self._value
        self._off_reconnect = self.runtime.on_reconnect(lambda _host: run_in_thread(self.refresh))
        try:
            self._stop = self.runtime.subscribe(
                self.node_type, self.key, self.topic, self._on_push
            )
            value = self.refresh()
        except BaseException:
            self.stop()
            raise
        self._started = True
        return value

    def stop(self) -> None:
        if self._off_reconnect is not None:
            self._off_reconnect()
            self._off_reconnect = None
        stop, self._stop = self._stop, None
        self._started = False
        if stop is not None:
            stop()

    def refresh(self) -> Any:
        """Reads the value again (one read at a time; a request during one runs after it)."""
        if self._reading.active:
            self._again = True
        return self._reading.run(self._read_all)

    def _read_all(self) -> Any:
        while True:
            self._again = False
            value = self._read()
            if not self._again:
                break
        self._value = value
        self._listeners.fire(value)
        return value

    def get(self) -> Any:
        return self._value

    def subscribe(self, listener: Callable[[Any], Any]) -> Callable[[], None]:
        return self._listeners.add(listener)

    def _on_push(self, push: ExecPush) -> None:
        msg = split_kit_message(push.value)
        if msg is None or msg[0].kind != "changed" or msg[1].get("what") not in self._whats:
            return
        who = [str(w) for w in msg[1].get("who") or []]

        def again() -> None:
            me = self.runtime.player_id()
            if me is None or me in who:
                self.refresh()

        run_in_thread(again)
